#include "runa_rtc_mock_hal.h"
#include <string.h>
static runa_status_t mock_read(void *context, uintptr_t handle, runa_rtc_time_t *time) { runa_rtc_mock_hal_t *mock = (runa_rtc_mock_hal_t *)context; runa_status_t status; (void)handle; if (mock == NULL || time == NULL) return RUNA_ERR_INVALID_FORMAT; ++mock->read_calls; status = mock->next_read_status; mock->next_read_status = RUNA_OK; if (status == RUNA_OK) *time = mock->current_time; return status; }
static runa_status_t mock_set(void *context, uintptr_t handle, const runa_rtc_time_t *time) { runa_rtc_mock_hal_t *mock = (runa_rtc_mock_hal_t *)context; runa_status_t status; (void)handle; if (mock == NULL || time == NULL) return RUNA_ERR_INVALID_FORMAT; ++mock->set_calls; status = mock->next_set_status; mock->next_set_status = RUNA_OK; if (!mock->set_supported) return RUNA_RTC_ERR_SET_UNSUPPORTED; if (status == RUNA_OK) { mock->last_set_time = *time; mock->current_time = *time; } return status; }
static runa_status_t mock_status(void *context, uintptr_t handle, uint32_t *flags) { runa_rtc_mock_hal_t *mock = (runa_rtc_mock_hal_t *)context; runa_status_t status; (void)handle; if (mock == NULL || flags == NULL) return RUNA_ERR_INVALID_FORMAT; ++mock->status_calls; status = mock->next_status_status; mock->next_status_status = RUNA_OK; if (status == RUNA_OK) *flags = mock->status_flags; return status; }
void runa_rtc_mock_hal_init(runa_rtc_mock_hal_t *mock) { if (mock == NULL) return; memset(mock, 0, sizeof *mock); mock->set_supported = 1u; }
runa_rtc_hal_t runa_rtc_mock_hal_interface(runa_rtc_mock_hal_t *mock) { runa_rtc_hal_t hal = { mock, mock_read, mock_set, mock_status }; return hal; }
